import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.CvydjLy7.js";const _=JSON.parse('{"title":"一、官方 Data 一章覆盖了什么","description":"","frontmatter":{"title":"一、官方 Data 一章覆盖了什么"},"headers":[{"level":3,"title":"1.1 案例项目的数据访问设计","slug":"_1-1-案例项目的数据访问设计","link":"#_1-1-案例项目的数据访问设计","children":[]}],"relativePath":"ch06/01.md","filePath":"ch06/01.md","lastUpdated":1789497795000}'),r={name:"ch06/01.md"};function c(i,t,s,l,n,h){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="一、官方-data-一章覆盖了什么" tabindex="-1">一、官方 Data 一章覆盖了什么 <a class="header-anchor" href="#一、官方-data-一章覆盖了什么" aria-label="Permalink to &quot;一、官方 Data 一章覆盖了什么&quot;">​</a></h1><p>官方的 Data 章节本身只有一句话——“Spring Boot 集成了多种数据技术，包括 SQL 与 NoSQL”，然后分成两大棵树：</p><table tabindex="0"><thead><tr><th>分支</th><th>官方覆盖的技术</th><th>本篇处理方式</th></tr></thead><tbody><tr><td>SQL</td><td>数据源与连接池、<code>JdbcTemplate</code> / <code>JdbcClient</code>、JPA、Spring Data JDBC、H2 控制台、jOOQ、R2DBC</td><td>重点讲数据源、<code>JdbcClient</code>、JPA 三条，R2DBC 与 jOOQ 简要带过</td></tr><tr><td>NoSQL</td><td>Redis、MongoDB、Elasticsearch、Cassandra、Neo4j、LDAP、InfluxDB</td><td>第十二节给选型要点，案例项目未引入，不做实测</td></tr></tbody></table><p>MyBatis-Plus 不在官方文档里——Spring Boot 官方只原生支持 JPA 与 Spring Data JDBC，MyBatis 是第三方生态。所以第十一节的内容全部来自 MyBatis-Plus 官方文档与本机实测。</p><h3 id="_1-1-案例项目的数据访问设计" tabindex="-1">1.1 案例项目的数据访问设计 <a class="header-anchor" href="#_1-1-案例项目的数据访问设计" aria-label="Permalink to &quot;1.1 案例项目的数据访问设计&quot;">​</a></h3><p>本项目的两个工程分别用两种技术实现同一套接口，可以直接对照：</p><table tabindex="0"><thead><tr><th></th><th><code>activity-server</code></th><th><code>activity-server-mybatisplus</code></th></tr></thead><tbody><tr><td>端口</td><td>8080</td><td>8081</td></tr><tr><td>映射方式</td><td>JPA 注解 + Hibernate 自动建表</td><td>MyBatis-Plus 注解 + 手写建表脚本</td></tr><tr><td>数据访问</td><td><code>JpaRepository</code> + <code>Specification</code></td><td><code>BaseMapper</code> + <code>LambdaQueryWrapper</code></td></tr><tr><td>表结构</td><td><code>ddl-auto: create-drop</code> 由框架生成</td><td><code>schema.sql</code> 人工维护</td></tr><tr><td>逻辑删除</td><td>实体方法里手工置位</td><td><code>@TableLogic</code> 由框架改写 SQL</td></tr><tr><td>测试数</td><td>42（第 7 篇新增 16 个，总计 58）</td><td>6</td></tr></tbody></table>',7)])])}const b=d(r,[["render",c]]);export{_ as __pageData,b as default};
